definition.script:
pipeline {
    agent any

    parameters {
        string(name: 'PROJECT_ID', defaultValue: '', description: 'ID del Proyecto')
        string(name: 'VERSION_DB', defaultValue: '12.1.0.2', description: 'Versión de Oracle DB')
    }

    environment {
        AZURE_REPO = "https://darias:FrEVryWWGJXSmIpurkWpflMLYIOvmUmpyiS6zcIrDUY4a3YlDMRQJQQJ99BDACAAAAAmugoDAAAGAZDO3Fy0@dev.azure.com/darias0313/Pruebas/_git/poc-corfi"
        DATA_RUTE_LOCAL = "/root/POC/jenkins-nexus/data/oraclebd/"
        DATA_RUTE = "${env.DATA_RUTE_LOCAL}"+"oraclebd-"+"${PROJECT_ID}"
    }

    stages {
        stage('Clonar repositorio') {
            steps {
                git url: "${env.AZURE_REPO}", branch: 'feature/test'
            }
        }

        stage('Crear Volumen y Permisos') {
            steps {
                 script {
                    sh """
                        cd ${env.DATA_RUTE_LOCAL}
                        ls -ltra
                        mkdir -p oracledb-${PROJECT_ID}
                        sudo chown -R 1000:1000 oracledb-${PROJECT_ID}
                        sudo chmod 644 oracledb-${PROJECT_ID}
                    """
                 }
            }
        }

        stage('Levantar Oracle con Docker Compose') {
            steps {
                script {
                    sh """
                        cd oracle-db
                        sed -i 's/{{PROJECT_ID}}/${PROJECT_ID}/g' docker-compose.yaml
                        sed -i 's|{{DATA_RUTE}}|${DATA_RUTE}|g' docker-compose.yaml
                        export PATH=$PATH:$HOME/.local/bin && podman-compose --version
                        docker-compose up -d
                    """
                }
            }
        }
    }
}
